let arrV = flow.get("co_yel_arr_v") || [];
let arrC = flow.get("co_yel_arr_c") || [];
let arrP = flow.get("co_yel_arr_p") || [];

let health = flow.get("co_yel_health") || false;
let lastV = flow.get("co_yel_last_v") || 0;
let lastC = flow.get("co_yel_last_c") || 0;
let lastP = flow.get("co_yel_last_p") || 0;

// Calculate Averages. Fallback to the last known static value if array is empty.
let avgV = arrV.length > 0 ? (arrV.reduce((a, b) => a + b, 0) / arrV.length).toFixed(2) : lastV.toFixed(2);
let avgC = arrC.length > 0 ? (arrC.reduce((a, b) => a + b, 0) / arrC.length).toFixed(3) : lastC.toFixed(3);
let avgP = arrP.length > 0 ? (arrP.reduce((a, b) => a + b, 0) / arrP.length).toFixed(1) : lastP.toFixed(1);

// Clear the arrays for the next 5 minute block
flow.set("co_yel_arr_v", []);
flow.set("co_yel_arr_c", []);
flow.set("co_yel_arr_p", []);

let date = new Date();
let timestamp = date.toLocaleString('en-US', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });

// A disconnected meter with an empty sample array would otherwise fall back to its
// frozen last value here and log it as if it were a real 5-minute average.
if (arrV.length === 0 && !health) return null;
msg.payload = [[ timestamp, Number(avgV), Number(avgC), Number(avgP) ]];
return msg;

