let timestamp = date.toLocaleString('en-US', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });

// A disconnected meter with an empty sample array would otherwise fall back to its
// frozen last value here and log it as if it were a real 5-minute average.
if (arrV.length === 0 && !health) return null;
msg.payload = [[ timestamp, Number(avgV), Number(avgC), Number(avgP) ]];
return msg;

// --- 1. FETCH REAL-TIME DATA ---
let h1 = flow.get("co_yel_health") || false;
let v1 = h1 ? (parseFloat(flow.get("co_yel_last_v")) || 0) : 0;
let c1 = h1 ? (parseFloat(flow.get("co_yel_last_c")) || 0) : 0;
let p1 = h1 ? (parseFloat(flow.get("co_yel_last_p")) || 0) : 0;

let h2 = flow.get("lo_red_health") || false;
let v2 = h2 ? (parseFloat(flow.get("lo_red_last_v")) || 0) : 0;
let c2 = h2 ? (parseFloat(flow.get("lo_red_last_c")) || 0) : 0;
let p2 = h2 ? (parseFloat(flow.get("lo_red_last_p")) || 0) : 0;

let h3 = flow.get("arec_health") || false;
let v3 = h3 ? (parseFloat(flow.get("arec_last_v")) || 0) : 0;
let c3 = h3 ? (parseFloat(flow.get("arec_last_c")) || 0) : 0;
let p3 = h3 ? (parseFloat(flow.get("arec_last_p")) || 0) : 0;

let h4 = flow.get("lo_yel2_health") || false;
let v4 = h4 ? (parseFloat(flow.get("lo_yel2_last_v")) || 0) : 0;
let c4 = h4 ? (parseFloat(flow.get("lo_yel2_last_c")) || 0) : 0;
let p4 = h4 ? (parseFloat(flow.get("lo_yel2_last_p")) || 0) : 0;

// --- 2. PHASE & POWER MATH ---
let currentRed = c2 + c3;
let currentYellow = c1 + c4;
let currentBlue = 0;

let totalPowerW = p1 + p2 + p3 + p4;
let totalDemandKW = totalPowerW / 1000;

let voltReadings = [v1, v2, v3, v4].filter(v => v > 0);
let avgVoltage = voltReadings.length > 0 ? (voltReadings.reduce((a, b) => a + b, 0) / voltReadings.length) : 0;

let date = new Date();
let timestamp = date.toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' });

// --- 3. SYNCHRONIZED ACCUMULATED ENERGY (kWh) ---
let tickHours = 2 / 3600;

// Calculate energy deltas for this specific 2-second tick
let deltaE1 = (p1 / 1000) * tickHours;
let deltaE2 = (p2 / 1000) * tickHours;
let deltaE3 = (p3 / 1000) * tickHours;
let deltaE4 = (p4 / 1000) * tickHours;
let totalDelta = deltaE1 + deltaE2 + deltaE3 + deltaE4;

// Update individual modules (Required for the module specific panels)
let e1 = parseFloat(flow.get("co_yel_energy")) || 0.0;
let e2 = parseFloat(flow.get("lo_red_energy")) || 0.0;
let e3 = parseFloat(flow.get("arec_energy")) || 0.0;
let e4 = parseFloat(flow.get("lo_yel2_energy")) || 0.0;

flow.set("co_yel_energy", e1 + deltaE1);
flow.set("lo_red_energy", e2 + deltaE2);
flow.set("arec_energy", e3 + deltaE3);
flow.set("lo_yel2_energy", e4 + deltaE4);

// Today's Energy
let currentEnergy = (e1 + deltaE1) + (e2 + deltaE2) + (e3 + deltaE3) + (e4 + deltaE4);
flow.set("bems_energy_today", currentEnergy);

// Week's Energy (Accumulates independently)
let weekEnergy = parseFloat(flow.get("bems_energy_week")) || 0;
weekEnergy += totalDelta;
flow.set("bems_energy_week", weekEnergy);

// Month's Energy (Accumulates independently)
let monthEnergy = parseFloat(flow.get("bems_energy_month")) || 0;
monthEnergy += totalDelta;
flow.set("bems_energy_month", monthEnergy);

let energyData = {
    today: currentEnergy.toFixed(3),
    week: weekEnergy.toFixed(2),
    month: monthEnergy.toFixed(2)
};

// --- 4. ROUTE OUTPUTS ---
return [
    { payload: Number(avgVoltage.toFixed(1)), topic: "System Voltage" },
    { payload: Number(currentRed.toFixed(2)), topic: "Phase Red" },
    { payload: Number(currentYellow.toFixed(2)), topic: "Phase Yellow" },
    { payload: Number(currentBlue.toFixed(2)), topic: "Phase Blue" },
    { payload: timestamp },
    { payload: Number(totalDemandKW.toFixed(3)), topic: "Total kW" },
    { payload: energyData }
];

let p = msg.payload;
let dps = (p && typeof p === 'object') ? (p.data && p.data.dps ? p.data.dps : p.dps) : null;

let isOnline = flow.get("co_yel_health") || false;
if (p === "CONNECTED" || (p.state && p.state === "CONNECTED")) isOnline = true;
else if (p === "DISCONNECTED" || p === "ERROR" || (p.state && (p.state === "DISCONNECTED" || p.state === "ERROR"))) isOnline = false;
else if (dps) isOnline = true;
flow.set("co_yel_health", isOnline);

let lastV = parseFloat(flow.get("co_yel_last_v")) || 0;
let lastC = parseFloat(flow.get("co_yel_last_c")) || 0;
let lastP = parseFloat(flow.get("co_yel_last_p")) || 0;

if (dps) {
    if (dps["107"] !== undefined) lastV = dps["107"] / 10;
    if (dps["106"] !== undefined) lastC = dps["106"] / 1000;
    if (dps["105"] !== undefined) lastP = dps["105"] / 10;
}

flow.set("co_yel_last_v", lastV);
flow.set("co_yel_last_c", lastC);
flow.set("co_yel_last_p", lastP);

// Fetch the perfectly synchronized energy from the main 2-second engine
let energy = parseFloat(flow.get("co_yel_energy")) || 0.0;

let arrV = flow.get("co_yel_arr_v") || []; let arrC = flow.get("co_yel_arr_c") || []; let arrP = flow.get("co_yel_arr_p") || [];
arrV.push(lastV); flow.set("co_yel_arr_v", arrV);
arrC.push(lastC); flow.set("co_yel_arr_c", arrC);
arrP.push(lastP); flow.set("co_yel_arr_p", arrP);

let timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' });
let uiData = { name: "C.O Yellow Module", titleColor: "#ffd700", voltage: lastV.toFixed(1), current: lastC.toFixed(3), power: lastP.toFixed(1), energy: energy.toFixed(3), status: isOnline ? "CONNECTED" : "DISCONNECTED", statusColor: isOnline ? "#00e676" : "#ff1744", time: timestamp };

return [ { payload: uiData }, { payload: lastP } ];

