return [ { payload: uiData }, { payload: lastP } ];

let date = new Date();
let dayOfWeek = date.getDay(); // 0 is Sunday, 1 is Monday, etc.
let dateOfMonth = date.getDate(); // 1-31

// 1. ALWAYS reset daily energy memory to exactly 0
flow.set("bems_energy_today", 0.0);
flow.set("co_yel_energy", 0.0);
flow.set("lo_red_energy", 0.0);
flow.set("arec_energy", 0.0);
flow.set("lo_yel2_energy", 0.0);

let msgStr = "Daily energy reset to 0.";

// 2. Weekly Reset Check
// Assumes the week ends Sunday night. At 12:00 AM Monday (day === 1), reset the week.
if (dayOfWeek === 1) {
    flow.set("bems_energy_week", 0.0);
    msgStr += " Weekly energy reset.";
}

// 3. Monthly Reset Check
// At 12:00 AM on the 1st of the month, reset the month.
if (dateOfMonth === 1) {
    flow.set("bems_energy_month", 0.0);
    msgStr += " Monthly energy reset.";
}

return { payload: msgStr };

// READ-ONLY. Reads this tab's flow context; writes nothing.
const keys = ['co_yel', 'lo_red', 'arec', 'lo_yel2'];
const meters = {};
for (const k of keys) {
  meters[k] = {
    v: flow.get(k + '_last_v'), c: flow.get(k + '_last_c'), p: flow.get(k + '_last_p'),
    e: flow.get(k + '_energy'), h: flow.get(k + '_health')
  };
}
msg.snapshot = msg.snapshot || {};
msg.snapshot.energy = {
  meters,
  totals: {
    today: flow.get('bems_energy_today'),
    week: flow.get('bems_energy_week'),
    month: flow.get('bems_energy_month')
  }
};
return msg;

// 1. Fetch the last known values that the Unified Parser saved
// This ensures that even if Tuya hasn't broadcasted an update in the last 3 mins, 
// you still log the current, real-world state of the outlet.
if (!(flow.get("co5_health") || false)) return null; // disconnected — don't log a frozen reading as real
let lastV = flow.get("co5_last_v") || 0;
let lastC = flow.get("co5_last_c") || 0;
let lastP = flow.get("co5_last_p") || 0;

// 2. Format the timestamp
let date = new Date(); 
let timestamp = date.toLocaleString('en-US', { 
    year: 'numeric', 
    month: '2-digit', 
    day: '2-digit', 
    hour: '2-digit', 
    minute: '2-digit', 
    second: '2-digit', 
    hour12: true 
});

// 3. Assemble the payload for Google Sheets
msg.payload = [[ timestamp, Number(lastV), Number(lastC), Number(lastP) ]];

return msg;

